import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../core/auth-service';
import { errorMessage } from '../core/http-error';

@Component({
  standalone: true,
  imports: [FormsModule],
  templateUrl: './login.html',
})
export class LoginPage {
  private readonly auth = inject(AuthService);
  private readonly router = inject(Router);
  readonly busy = signal(false);
  readonly error = signal('');
  email = '';
  password = '';

  constructor() {
    if (this.auth.user()) {
      void this.router.navigateByUrl('/records');
    }
  }

  submit(): void {
    if (this.busy()) {
      return;
    }

    this.busy.set(true);
    this.error.set('');

    this.auth.login(this.email, this.password).subscribe({
      next: () => {
        this.password = '';
        this.busy.set(false);
        void this.router.navigateByUrl('/records');
      },
      error: (error) => {
        this.error.set(errorMessage(error));
        this.busy.set(false);
      },
    });
  }
}
<div class="login-page">
  <section class="login-story">
    <a class="brand" href="/">
      <span class="mountain" aria-hidden="true">△</span>
      <span>Salkantay<small>GESTIÓN DE REGISTROS</small></span>
    </a>
    <div class="story-copy">
      <h1>Gestión de registros</h1>
      <p>Consulta, organiza y actualiza tu información.</p>
    </div>
    <small class="story-footer">Espacio personal</small>
  </section>

  <section class="login-form">
    <div class="login-card">
      <h2>Iniciar sesión</h2>
      <p class="muted">Ingresa tus datos para continuar.</p>

      <form (ngSubmit)="submit()" #form="ngForm">
        <label for="email">Correo electrónico</label>
        <input
          id="email"
          name="email"
          type="email"
          [(ngModel)]="email"
          required
          email
          autocomplete="username"
          placeholder="tu@correo.com"
          [disabled]="busy()"
        >

        <label for="password">Contraseña</label>
        <input
          id="password"
          name="password"
          type="password"
          [(ngModel)]="password"
          required
          maxlength="255"
          autocomplete="current-password"
          placeholder="Tu contraseña"
          [disabled]="busy()"
        >

        @if (error()) {
          <p class="alert error" role="alert">{{ error() }}</p>
        }

        <button class="primary full" type="submit" [disabled]="form.invalid || busy()">
          {{ busy() ? 'Ingresando…' : 'Iniciar sesión' }}
        </button>
      </form>
    </div>
  </section>
</div>
